js <- "
document.addEventListener('DOMContentLoaded', function() {
  var tex = function(el) {
    if (!window.renderMathInElement) return;
    renderMathInElement(el, {delimiters: [{left: '\\\\(', right: '\\\\)', display: false},
                                          {left: '\\\\[', right: '\\\\]', display: true}], throwOnError: false});
  };
  tex(document.body);
  new MutationObserver(function(ms) {
    ms.forEach(function(m) { if (m.addedNodes.length) tex(m.target); });
  }).observe(document.body, {childList: true, subtree: true});
});
// Tick labels at chosen values on the log-scale alpha slider, placed as ion.rangeSlider places its own grid
function tks() {
  try {
    var s = $('#alpha').data('ionRangeSlider'), r = $('#aw .irs').first();
    if (!s || !r.length || r.find('.tks').length) return;
    var w = r.find('.irs-handle').outerWidth() || 0;
    var d = $('<div class=\"tks\"></div>');
    [0.001, 0.01, 0.05, 0.1].forEach(function(v) {
      var f = (Math.log10(v) - s.options.min) / (s.options.max - s.options.min);
      d.append($('<span></span>').text(v).css('left', 'calc(' + w / 2 + 'px + ' + f + ' * (100% - ' + w + 'px))'));
    });
    r.append(d);
  } catch (e) {}
}
$(document).on('shiny:connected', function() { setTimeout(tks, 0); });
var lockQ = false;
function applyLock() { $('#chk, #gr input').prop('disabled', lockQ); }
Shiny.addCustomMessageHandler('lock', function(a) {
  lockQ = a;
  applyLock();
});
$(document).on('shiny:value', function(e) { if (e.name === 'q') setTimeout(applyLock, 0); });
Shiny.addCustomMessageHandler('fin', function(x) {
  $('#nq').prop('disabled', x.nq);
  $('#qb').toggleClass('off', x.box);
});
function check() {
  var a = [];
  $('#gr tbody tr').each(function() { a.push($(this).find('input:checked').val() || ''); });
  Shiny.setInputValue('chk', a.join(','), {priority: 'event'});
}
$(document).on('click', '#chk', check);
$(document).on('keydown', '#gr input', function(e) {
  if (e.key === 'Enter') {
    e.preventDefault();
    check();
  }
});
var skey = 'rodenburg-apps:error-rates:v1';
$(document).on('shiny:connected', function() {
  var ok = false, rec = null;
  try {
    localStorage.setItem(skey + ':test', '1');
    localStorage.removeItem(skey + ':test');
    ok = true;
    rec = JSON.parse(localStorage.getItem(skey));
  } catch (e) {}
  Shiny.setInputValue('store', {ok: ok, rec: rec});
});
Shiny.addCustomMessageHandler('put', function(x) {
  try { localStorage.setItem(skey, JSON.stringify(x)); } catch (e) {}
});
Shiny.addCustomMessageHandler('yay', function(x) { try { parent.yay(); } catch (e) {} });
function resetScores() {
  if (confirm('Reset all scores? This cannot be undone.')) Shiny.setInputValue('reset_sc', true, {priority: 'event'});
}
// Color scheme, shared with the book: Quarto's key, 'default' = light, 'alternate' = dark, none = system
var dmK = 'quarto-color-scheme', dmN = {light: 'Light', dark: 'Dark', system: 'System'};
var dmQ = window.matchMedia('(prefers-color-scheme: dark)');
try { dmQ = window.top.matchMedia('(prefers-color-scheme: dark)'); } catch (e) {}
function dmGet() { try { return localStorage.getItem(dmK); } catch (e) { return null; } }
function dmChoice() { var s = dmGet(); return s === 'alternate' ? 'dark' : s === 'default' ? 'light' : 'system'; }
function dmDark() { var c = dmChoice(); return c === 'dark' || (c === 'system' && dmQ.matches); }
function dmShow() {
  var c = dmChoice(), d = dmDark();
  document.documentElement.classList.toggle('dm-dark', d);
  document.documentElement.style.colorScheme = d ? 'dark' : '';
  $('#dm .dm-btn').attr('aria-label', 'Color scheme: ' + dmN[c]);
  $('#dm .dm-i').each(function() { this.style.display = this.getAttribute('data-choice') === c ? '' : 'none'; });
  $('#dm .dropdown-menu a').each(function() {
    var on = this.getAttribute('data-choice') === c;
    $(this).attr('aria-checked', on ? 'true' : 'false').parent().toggleClass('active', on);
  });
  $('#dm').trigger('dmchange');
}
dmShow();
var dmB = new Shiny.InputBinding();
$.extend(dmB, {
  find: function(scope) { return $(scope).find('#dm'); },
  getValue: function() { return dmDark(); },
  subscribe: function(el, cb) { $(el).on('dmchange.dm', function() { cb(); }); },
  unsubscribe: function(el) { $(el).off('.dm'); }
});
Shiny.inputBindings.register(dmB, 'dm');
$(dmShow);
$(document).on('click', '#dm .dropdown-menu a', function(e) {
  e.preventDefault();
  var c = this.getAttribute('data-choice');
  try { if (c === 'system') localStorage.removeItem(dmK); else localStorage.setItem(dmK, c === 'dark' ? 'alternate' : 'default'); } catch (x) {}
  dmShow();
});
window.addEventListener('storage', function(e) { if (e.key === dmK || e.key === null) dmShow(); });
if (dmQ.addEventListener) dmQ.addEventListener('change', dmShow); else if (dmQ.addListener) dmQ.addListener(dmShow);
"

kx <- "https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.11/"

sch <- list(light = c("sun", "Light"), dark = c("moon", "Dark"), system = c("circle-half-stroke", "System"))

ico <- function(k) fontawesome::fa(sch[[k]][1], prefer_type = "regular")

