           tags$button(type = "button", class = "dm-btn", `data-toggle` = "dropdown", `aria-haspopup` = "true",
                       `aria-expanded` = "false", title = "Color scheme", `aria-label` = "Color scheme: System",
                       lapply(names(sch), function(k) span(class = "dm-i", `data-choice` = k,
                                                           style = if (k != "system") "display: none;", ico(k)))),
           tags$ul(class = "dropdown-menu dropdown-menu-right", role = "menu",
                   lapply(names(sch), function(k) tags$li(
                     role = "none", tags$a(href = "#", role = "menuitemradio", `aria-checked` = "false",
                                           `data-choice` = k, span(class = "dm-ic", ico(k)), sch[[k]][2])))))

ui <- fluidPage(
  tags$head(tags$link(rel = "stylesheet", href = paste0(kx, "katex.min.css")),
            tags$script(src = paste0(kx, "katex.min.js"), defer = NA),
            tags$script(src = paste0(kx, "contrib/auto-render.min.js"), defer = NA),
            tags$style(HTML(css)), tags$script(HTML(js))),
  div(id = "top", titlePanel("Interactive App — Error Rates", windowTitle = "Interactive App — Error Rates"),
      radioButtons("mode", "Mode:", c(Quiz = "quiz", Explore = "explore"), "quiz", inline = TRUE), dmm),
  conditionalPanel("input.mode == 'quiz'",
                   p("Five short questions on how often a test gets it wrong. If you are unsure, watch it happen in Explore.")),
  hr(),
  conditionalPanel("input.mode != 'quiz'",
                   div(id = "tw", span("The compound:"),
                       div(id = "truth", class = "shiny-input-radiogroup btn-group", `data-toggle` = "buttons",
                           role = "radiogroup", `aria-label` = "The compound",
                           tags$label(class = "btn btn-default active",
                                      tags$input(type = "radio", name = "truth", value = "h0", checked = NA), "does nothing"),
                           tags$label(class = "btn btn-default",
                                      tags$input(type = "radio", name = "truth", value = "h1"), "lowers blood pressure"))),
                   h3(id = "qw", textOutput("qh")),
                   div(id = "main",
                       div(id = "allw", div(class = "hd", h4(textOutput("cih"))),
                           imageOutput("all", height = "auto", hover = hoverOpts("hov", delay = 150, delayType = "throttle"),
                                       click = "clk"),
                           uiOutput("cap")),
                       div(id = "side",
                           uiOutput("tab"),
                           p(id = "note", class = "mut", "Move a slider and watch the percentage."),
                           div(class = "lg", sliderInput("n", tagList("Patients per trial: \\(n\\) = ", textOutput("nv", inline = TRUE)),
                                                         log10(3), log10(200), log10(30), step = 0.005, ticks = FALSE, width = "100%")),
                           div(id = "aw", class = "lg",
                               sliderInput("alpha", tagList("Significance level: \\(\\alpha\\) = ", textOutput("av", inline = TRUE)),
                                           -3, -1, log10(0.05), step = 0.01, ticks = FALSE, width = "100%")),
                           conditionalPanel("input.truth == 'h1'", div(class = "lg",
                             sliderInput("eff", tagList("True effect: a drop of ", textOutput("effv", inline = TRUE), " mmHg"),
                                         log10(0.5), log10(20), log10(5), step = 0.01, ticks = FALSE, width = "100%"))),
                           div(id = "run",
                               actionButton("play", "Play", icon = icon("play")),
                               actionButton("reset", "Reset"),
                               checkboxInput("show", "Show patients", FALSE)),
                           conditionalPanel("input.show", div(class = "hd", h4(textOutput("lh"))), imageOutput("last", height = "auto"))))),
  conditionalPanel("input.mode == 'quiz'", id = "qb",
                   div(class = "qnav", span(class = "mut", textOutput("pos", inline = TRUE)),
                       actionButton("prev", "Previous", class = "btn-sm"), actionButton("nxt", "Next", class = "btn-sm")),
                   uiOutput("q"),
                   tags$button(id = "chk", type = "button", class = "btn btn-default", "Check answer"),
                   actionButton("nq", "New question"),
                   uiOutput("fb")),
  conditionalPanel("input.mode == 'quiz'", uiOutput("ck"))
)

server <- function(input, output, session) {
  S   <- reactiveVal(NULL)
  geo <- reactiveVal(NULL)
  clk <- reactiveVal(NULL)
  a   <- reactive(signif(10^input$alpha, 2))
  E   <- reactive(signif(10^input$eff, 2))
  nn  <- reactive(round(10^input$n))
  h0  <- reactive(identical(input$truth, "h0"))

  draw <- function(k) list(u = rnorm(k), w = runif(k), s = sample.int(.Machine$integer.max, k))

  observeEvent(list(input$reset, input$truth), {
    S(draw(K))
    clk(NULL)
  }, ignoreNULL = FALSE)

  on <- reactiveVal(FALSE)
  play <- function(v) {
    on(v)
    updateActionButton(session, "play", label = if (v) "Pause" else "Play", icon = icon(if (v) "pause" else "play"))
  }
  observeEvent(input$play, play(!on()))
  observe({
    req(on())
    invalidateLater(1000 / spd)
    isolate(S(Map(c, req(S()), draw(1))))
  })

  V <- reactive({
    df <- nn() - 1
    sqrt(qchisq(req(S())$w, df) / df)
  })

  D <- reactive({
    x <- req(S())
    n <- nn()
    est <- (if (h0()) 0 else -E()) + sig * x$u / sqrt(n)
    se <- sig * V() / sqrt(n)
    t <- est / se
    list(n = n, eff = E(), h0 = h0(), est = est, se = se, t = t, p = 2 * pt(-abs(t), n - 1), s = x$s)
  })

  output$qh <- renderText(if (h0()) "How often does the test claim an effect?" else "How often does the test miss the effect?")

  output$effv <- renderText(format(E()))
  output$nv   <- renderText(nn())
  output$av   <- renderText(format(a()))

  observeEvent(input$clk, clk(hit(input$clk, isolate(geo()))))
  sel <- reactive({
    N <- length(D()$est)
    i <- hit(input$hov, geo())
    if (is.null(i)) i <- clk()
    if (is.null(i) || i > N) N else i
  })

  hh <- reactive({
    w <- session$clientData$output_all_width
    if (is.null(w)) 300 else round(min(max(0.55 * w, 260), 380))
  })

  img <- function(id, f, alt) renderImage({
    wd <- req(session$clientData[[paste0("output_", id, "_width")]])
    x <- D()
    h <- hh()
    p <- pal[[if (isTRUE(input$dm)) "dark" else "light"]]
    fn <- tempfile(fileext = ".svg")
    svg(fn, width = wd / 96, height = h / 96, bg = p[["bg"]])
    on.exit(dev.off())
    par(cex = 0.83, fg = p[["fg"]], col.axis = p[["fg"]], col.lab = p[["fg"]], col.main = p[["fg"]], mgp = c(2.75, 0.75, 0))
    f(x, p, wd, h)
    list(src = fn, width = wd, height = h, contentType = "image/svg+xml", alt = alt)
  }, deleteFile = TRUE)

  output$all <- img("all", function(x, p, wd, h) geo(c(pci(x, a(), p), w = wd, h = h)),
                    "Confidence intervals of the last 50 trials.")
  output$last <- img("last", function(x, p, wd, h) plast(x, sel(), a(), p),
                     "Strip chart of the change in blood pressure of each patient in one trial, with its average.")

  output$lh <- renderText({
    i <- sel()
    N <- length(D()$est)
    if (i == N) "Latest trial" else sprintf("Trial %s of %s", format(i, big.mark = ","), format(N, big.mark = ","))
  })

  output$cih <- renderText(sprintf("%g%% confidence intervals", 100 * (1 - a())))

  output$cap <- renderUI(p(class = "mut", "Last 50 trials, latest at the top. Red: the test got it wrong.",
                           if (isTRUE(input$show)) " Point at an interval to see that trial's patients."))

  output$tab <- renderUI({
    x <- D()
    lr <- if (x$h0) sprintf("%g%% (\\(\\alpha\\))", 100 * a()) else sprintf("%.1f%% (\\(\\beta\\))", 100 * (1 - pw(x$eff, sig, x$n, a())))
    tagList(div(id = "big", class = "rej", sprintf("%.1f%%", 100 * mean(wr(x, a()))),
                span(if (x$h0) "false positives" else "false negatives")),
            div(id = "bs", class = "mut", sprintf("of %s trials · long run: %s", format(length(x$est), big.mark = ","), lr)))
  })

  # ---- Quiz ----
  H   <- reactiveVal(list())
  pos <- reactiveVal(0)
  bad <- reactiveVal(FALSE)
  rec <- reactiveVal(character(0))
  ld  <- reactiveVal(FALSE)

  md     <- reactive(identical(input$mode, "quiz"))
  cq     <- reactive(if (pos() > 0) H()[[pos()]])
  latest <- reactive(pos() == length(H()))
  lk     <- reactive(!latest() || !is.null(cq()$res))
  dn     <- reactive(all(cells %in% rec()))

  put <- function() if (ld()) session$sendCustomMessage("put", list(v = 1, done = as.list(rec())))

  observeEvent(input$store, {
    r <- input$store$rec
    if (is.list(r) && identical(as.numeric(unlist(r$v)), 1)) rec(union(rec(), intersect(as.character(unlist(r$done)), cells)))
    ld(TRUE)
    put()
    if (md() && !length(H())) qnew()
  })

  # The next question without a checkmark, after the last one asked
  qnew <- function() {
    u <- setdiff(cells, rec())
    if (!length(u)) return()
    i <- if (length(H())) match(H()[[length(H())]]$q$id, cells) else 0
    H(c(H(), list(list(q = qchg(u[c(which(match(u, cells) > i), 1)[1]]), res = NULL))))
    pos(length(H()))
    bad(FALSE)
  }

  observeEvent(input$reset_sc, {
    rec(character(0))
    put()
    H(list())
    pos(0)
    qnew()
  })

  observeEvent(input$mode, if (md()) {
    if (on()) play(FALSE)
    if (!length(H())) qnew()
  }, ignoreInit = TRUE)

  observeEvent(input$go, updateRadioButtons(session, "mode", selected = "explore"))

  observeEvent(input$nq, if (md()) qnew())
  observeEvent(input$prev, pos(max(1, pos() - 1)))
  observeEvent(input$nxt, pos(min(length(H()), pos() + 1)))

  observeEvent(input$chk, {
    req(md(), !lk())
    e <- req(cq())
    a <- input$chk
    req(length(a) == 1)
    v <- qck(e$q, a)
    bad(is.na(v))
    req(!is.na(v))
    h <- H()
    h[[pos()]]$res <- list(v = v, a = a)
    H(h)
    if (v == "ok" && !e$q$id %in% rec()) {
      rec(c(rec(), e$q$id))
      put()
      if (dn()) session$sendCustomMessage("yay", TRUE)
    }
  })

  observe(session$sendCustomMessage("lock", lk()))
  observe(session$sendCustomMessage("fin", list(nq = dn(), box = dn() && !length(H()))))

  output$pos <- renderText(sprintf("Question %d of %d", match(req(cq())$q$id, cells), length(cells)))

  output$q <- renderUI({
    e <- req(cq())
    tagList(div(class = "qt", HTML(e$q$text)), qgrid(e$q, e$res$a))
  })

  output$fb <- renderUI({
    e <- req(cq())
    if (is.null(e$res)) return(if (!latest()) div(class = "alert alert-secondary", qs$na) else if (bad()) div(class = "mut", qs$chg$nan))
    f <- qfb(e$q, e$res$a)
    tagList(div(class = paste0("alert fb-", f$col), HTML(f$html)),
            if (e$res$v == "no") tags$button(id = "go", type = "button", class = "btn btn-default btn-sm",
                                             onclick = "Shiny.setInputValue('go', true, {priority: 'event'})", qs$go))
  })

  output$ck <- renderUI({
    d <- rec()
    tagList(h4(qs$done),
            div(style = "overflow-x: auto;", tags$table(class = "table table-condensed", style = "width: auto;",
              tags$thead(tags$tr(lapply(cells, function(z) tags$th(style = "text-align: center;", qs$lab[[z]])))),
              tags$tbody(tags$tr(lapply(cells, function(z) tags$td(style = "text-align: center;",
                                                                    if (z %in% d) span(style = "color: #4393c3;", "✓"))))))),
            if (dn()) p(HTML(qs$end)),
            if (length(d)) tags$button(type = "button", class = "btn btn-default btn-sm", onclick = "resetScores()", "Reset scores"))
  })
}

shinyApp(ui, server)
